var sv = SugarCube.State.variables;
// Find Frank's UUID
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k] && sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
window._frankUuid = frankUuid;
'frank_uuid=' + frankUuid + ' time=' + (sv.game_state && sv.game_state.time_state ? sv.game_state.time_state.current_hour : '?');

var sv = SugarCube.State.variables;
// Cheap probe: list NPC keys + slugs
var out = [];
for (var k in sv.npcs) {
    var n = sv.npcs[k];
    if (n && n.slug) out.push(n.slug + '=' + k.substring(0, 8));
}
window._npc_list = out.join(', ');
out.length;

var sv = SugarCube.State.variables;
// 1. Set the bedroom invitation flag (capstone already fired)
sv.flagBag = sv.flagBag || {};
sv.flagBag.frank_invited_to_bedroom = true;
sv.flagBag.frank_bedroom_first_done = false;
sv.flagBag.talked_to_frank_today = false;
// 2. Player corruption to 30 (passes the cascade Beat 3 gate at 25)
sv.player.core_traits.corruption = 30;
// 3. Find Frank UUID and set his arousal to 0 so we can see +2 from Beat 2 click
var frankUuid = null;
for (var k in sv.npcs) {
  if (sv.npcs[k] && sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; }
}
if (frankUuid) {
  sv.npcs[frankUuid].core_traits = sv.npcs[frankUuid].core_traits || {};
  sv.npcs[frankUuid].core_traits.arousal = 0;
}
// 4. Force time to weekday evening 21:30
if (sv.game_state && sv.game_state.time_state) {
  sv.game_state.time_state.current_hour = 21;
  sv.game_state.time_state.current_minute = 30;
  sv.game_state.time_state.current_day_of_week = 'monday';
}
'frankUuid=' + frankUuid;

var sv = SugarCube.State.variables;
var frankUuid = null;
for (var k in sv.npcs) {
  if (sv.npcs[k] && sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; }
}
var probe = {
  npc_frank_stage_trait: sv.player.core_traits.npc_frank_stage,
  frank_invited_in_flagBag: sv.flagBag && sv.flagBag.frank_invited_to_bedroom,
  frank_invited_in_player_flagBag: sv.player.flagBag && sv.player.flagBag.frank_invited_to_bedroom,
  bedroom_first_done: sv.flagBag && sv.flagBag.frank_bedroom_first_done,
  talked_today: sv.flagBag && sv.flagBag.talked_to_frank_today,
  player_corruption: sv.player.core_traits.corruption,
  frank_arousal: frankUuid ? sv.npcs[frankUuid].core_traits.arousal : 'NO_UUID',
  current_hour: sv.game_state && sv.game_state.time_state && sv.game_state.time_state.current_hour,
  current_day: sv.game_state && sv.game_state.time_state && sv.game_state.time_state.current_day_of_week,
  // Show all flag stores
  player_flagBag_keys: sv.player && sv.player.flagBag ? Object.keys(sv.player.flagBag).slice(0,30) : 'none',
  global_flagBag_keys: sv.flagBag ? Object.keys(sv.flagBag).slice(0,30) : 'none'
};
window._tgeProbe = JSON.stringify(probe, null, 2);
document.title = 'PROBE: ' + window._tgeProbe.substring(0, 200);
'set';

var sv = SugarCube.State.variables;
sv.player.flagBag = sv.player.flagBag || {};
sv.player.flagBag.frank_invited_to_bedroom = true;
sv.player.flagBag.frank_bedroom_first_done = false;
sv.player.flagBag.talked_to_frank_today = false;
'set in player.flagBag'

// Grab passage list from Story to find the right bedroom canvas passage name
var pNames = Object.keys(Story.passages).filter(function(n){
  return n.toLowerCase().indexOf('bedroom') !== -1 && n.toLowerCase().indexOf('frank') !== -1;
});
window._matchedPassages = pNames.join(' | ');
pNames.length;

var sv = SugarCube.State.variables;
sv.player.core_traits.corruption = 10;  // Below 25 — gate should fail
sv.player.flagBag.frank_bedroom_first_done = false;  // Reset to first night
// Reset Frank arousal so we can re-verify the +2 effect
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
if (frankUuid) sv.npcs[frankUuid].core_traits.arousal = 0;
SugarCube.Engine.play('Canvas_scene_franks_bedroom_evening_Node_1');
'reloaded'

var sv = SugarCube.State.variables;
sv.player.flagBag.frank_bedroom_first_done = true;  // Switch to subsequent-night branch
sv.player.flagBag.talked_to_frank_today = false;
SugarCube.Engine.play('Canvas_scene_franks_bedroom_evening_Node_1');
'switched'

// Use the engine's own flag-set mechanism instead of direct write
setup.applyAndNotifyFlag('player', null, 'frank_bedroom_first_done', 'set');
setup.applyAndNotifyFlag('player', null, 'talked_to_frank_today', 'unset');
SugarCube.Engine.play('Canvas_scene_franks_bedroom_evening_Node_1');
'engine-flagged'

var sv = SugarCube.State.variables;
// Check all the places frank_bedroom_first_done could live
var probe = {
  player_flagBag: sv.player.flagBag && sv.player.flagBag.frank_bedroom_first_done,
  player_flags: sv.player.flags && sv.player.flags.frank_bedroom_first_done,
  player_flag_keys: sv.player.flagBag ? Object.keys(sv.player.flagBag).filter(function(k){return k.indexOf('frank')>=0}) : [],
  // Try the engine's flag check
  trigger_checks_first_done_true: setup.triggerConditionsSatisfied({version:'1.0', logic:'AND', items:[{type:'flag', subject:'player', flag_key:'frank_bedroom_first_done', operator:'is_true'}]}),
  trigger_checks_first_done_false: setup.triggerConditionsSatisfied({version:'1.0', logic:'AND', items:[{type:'flag', subject:'player', flag_key:'frank_bedroom_first_done', operator:'is_false'}]}),
};
document.title = 'PROBE2:' + JSON.stringify(probe);
'set'
